package android.webkit;
import android.content.Context;
import android.view.View;
import android.view.KeyEvent;
import java.io.*;
import java.util.Base64;
import java.util.concurrent.*;
/** Experimental embedded Chromium renderer, not a web replacement for an APK. */
public class WebView extends View {
 private final WebSettings settings=new WebSettings(this);private WebViewClient client=new WebViewClient();private String url;private volatile boolean destroyed;private Process process;private BufferedWriter writer;private BufferedReader reader;
 private final ExecutorService commands=Executors.newSingleThreadExecutor(new ThreadFactory(){public Thread newThread(Runnable r){Thread t=new Thread(r,"WebView-Chromium");t.setDaemon(true);return t;}});
 public WebView(Context c){super(c);canvasDrawing=false;setFocusable(true);}public WebView(Context c,android.util.AttributeSet a){this(c);}public WebView(Context c,android.util.AttributeSet a,int style){this(c);}
 public WebSettings getSettings(){return settings;}public void setWebViewClient(WebViewClient c){client=c==null?new WebViewClient():c;}public String getUrl(){return url;}
 private String request(String op,String arg)throws IOException{if(destroyed)throw new IllegalStateException("WebView destroyed");if(process==null){File data=new File(getContext().getFilesDir(),"webview-"+bridgeId);if(!data.isDirectory()&&!data.mkdirs())throw new IOException("Cannot create WebView data");process=new ProcessBuilder("/usr/bin/python3","/runtime/webview.py",data.getPath()).redirectError(ProcessBuilder.Redirect.INHERIT).start();writer=new BufferedWriter(new OutputStreamWriter(process.getOutputStream(),"UTF-8"));reader=new BufferedReader(new InputStreamReader(process.getInputStream(),"UTF-8"));}writer.write(op+"|"+Base64.getEncoder().encodeToString(arg.getBytes("UTF-8"))+"\n");writer.flush();String line=reader.readLine();if(line==null||line.length()>12*1024*1024||!line.contains("|"))throw new IOException("WebView renderer response invalid");String value=new String(Base64.getDecoder().decode(line.substring(line.indexOf('|')+1)),"UTF-8");if(!line.startsWith("OK|"))throw new IOException(value);return value;}
 private void screenshot()throws IOException{final byte[] png=Base64.getDecoder().decode(request("P",""));if(Boolean.getBoolean("padbridge.headless"))java.nio.file.Files.write(java.nio.file.Paths.get("/data/webview-"+bridgeId+".png"),png);post(new Runnable(){public void run(){if(!destroyed)org.padtv.bridge.Native.image(bridgeId,png);}});}
 private void failure(final Exception e){System.err.println("PADBRIDGE_WEBVIEW_ERROR: "+e);post(new Runnable(){public void run(){if(!destroyed)client.onReceivedError(WebView.this,-1,e.toString(),url);}});}
 void bridgeSetting(final boolean enabled){commands.execute(new Runnable(){public void run(){try{request("S",enabled?"1":"0");}catch(Exception e){failure(e);}}});}
 private void navigate(final String op,final String value,final String display){if(destroyed)throw new IllegalStateException();if(client.shouldOverrideUrlLoading(this,display))return;url=display;client.onPageStarted(this,url,null);commands.execute(new Runnable(){public void run(){try{request(op,value);screenshot();post(new Runnable(){public void run(){if(!destroyed)client.onPageFinished(WebView.this,display);}});}catch(Exception e){failure(e);}}});}
 public void loadUrl(String u){if(!u.startsWith("http://")&&!u.startsWith("https://"))throw new UnsupportedOperationException("WebView URL scheme");navigate("L",u,u);}
 public void loadData(String data,String mime,String encoding){if(!mime.equals("text/html")||(!encoding.equalsIgnoreCase("UTF-8")&&!encoding.equalsIgnoreCase("base64")))throw new UnsupportedOperationException("WebView data format");try{navigate("H",encoding.equalsIgnoreCase("base64")?new String(Base64.getDecoder().decode(data),"UTF-8"):data,"data:text/html");}catch(UnsupportedEncodingException e){throw new AssertionError(e);}}
 public void evaluateJavascript(final String script,final ValueCallback<String> callback){if(destroyed)throw new IllegalStateException();commands.execute(new Runnable(){public void run(){try{final String result=request("J",script);screenshot();post(new Runnable(){public void run(){if(!destroyed&&callback!=null)callback.onReceiveValue(result);}});}catch(Exception e){failure(e);}}});}
 public boolean dispatchKeyEvent(final KeyEvent event){if(event.getAction()!=0)return true;if(event.getKeyCode()!=19&&event.getKeyCode()!=20&&event.getKeyCode()!=21&&event.getKeyCode()!=22&&event.getKeyCode()!=23&&event.getKeyCode()!=66&&event.getKeyCode()!=61)return false;commands.execute(new Runnable(){public void run(){try{request("K",String.valueOf(event.getKeyCode()));screenshot();}catch(Exception e){failure(e);}}});return true;}
 public void destroy(){destroyed=true;commands.shutdownNow();if(process!=null){process.destroy();try{if(!process.waitFor(3,TimeUnit.SECONDS))process.destroyForcibly();}catch(InterruptedException e){Thread.currentThread().interrupt();}try{reader.close();writer.close();}catch(IOException e){System.err.println(e);}}}
}
